from fractions import Fraction
from collections import deque


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = {a: b for a, b in jumps}

    def resolve(c: int) -> int:
        # Follow jump chains; the problem guarantees they terminate.
        while c in jump:
            c = jump[c]
        return c

    def successors(p: int) -> list[int]:
        res = []
        for r in range(1, m + 1):
            q = p + r if p + r <= n else 2 * n - p - r
            res.append(resolve(q))
        return res

    # Explore the states reachable from the start cell 0.
    trans = {}
    seen = {0}
    dq = deque([0])
    while dq:
        p = dq.popleft()
        succ = successors(p)
        trans[p] = succ
        for q in succ:
            if q != n and q not in seen:
                seen.add(q)
                dq.append(q)

    # The game ends with probability 1 only if every reachable state can reach n.
    good = set()
    changed = True
    while changed:
        changed = False
        for p in seen:
            if p not in good and any(q == n or q in good for q in trans[p]):
                good.add(p)
                changed = True
    if len(good) != len(seen):
        return None

    # E[p] = 1 + (1/m) * sum(E[q]) over reachable non-terminal states, with E[n] = 0.
    # Multiplying each equation by m keeps the coefficients integral.
    nodes = sorted(seen)
    idx = {p: i for i, p in enumerate(nodes)}
    k = len(nodes)
    A = [[Fraction(0)] * (k + 1) for _ in range(k)]
    for p in nodes:
        i = idx[p]
        A[i][i] += m
        A[i][k] = Fraction(m)
        for q in trans[p]:
            if q != n:
                A[i][idx[q]] -= 1

    # Gauss-Jordan elimination with exact fractions.
    for col in range(k):
        piv = next(r for r in range(col, k) if A[r][col] != 0)
        A[col], A[piv] = A[piv], A[col]
        pv = A[col][col]
        A[col] = [x / pv for x in A[col]]
        for r in range(k):
            if r != col and A[r][col] != 0:
                f = A[r][col]
                A[r] = [x - f * y for x, y in zip(A[r], A[col])]

    ans = A[idx[0]][k]
    return [ans.numerator, ans.denominator]
